CREATE DATABASE IF NOT EXISTS library_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE library_management;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','member') NOT NULL DEFAULT 'member',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS members (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL UNIQUE,member_code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,email VARCHAR(190),phone VARCHAR(40),status ENUM('active','inactive','suspended') NOT NULL DEFAULT 'active',membership_expiry DATE NULL,max_books INT NOT NULL DEFAULT 5,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_member_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS books (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,author VARCHAR(180) NOT NULL,isbn VARCHAR(60),category VARCHAR(100),publisher VARCHAR(180),shelf VARCHAR(80),total_copies INT NOT NULL DEFAULT 1,available_copies INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(title),INDEX(isbn)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS loans (id INT AUTO_INCREMENT PRIMARY KEY,member_id INT NOT NULL,book_id INT NOT NULL,quantity INT NOT NULL DEFAULT 1,issue_date DATE NOT NULL,due_date DATE NOT NULL,return_date DATE NULL,status ENUM('issued','returned') NOT NULL DEFAULT 'issued',issued_by INT NULL,returned_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(issued_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(returned_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,due_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fines (id INT AUTO_INCREMENT PRIMARY KEY,loan_id INT NOT NULL UNIQUE,member_id INT NOT NULL,book_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('unpaid','paid','waived') NOT NULL DEFAULT 'unpaid',paid_at DATETIME NULL,note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(loan_id) REFERENCES loans(id),FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(book_id) REFERENCES books(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservations (id INT AUTO_INCREMENT PRIMARY KEY,member_id INT NOT NULL,book_id INT NOT NULL,status ENUM('pending','approved','rejected','fulfilled','cancelled') NOT NULL DEFAULT 'pending',request_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,note VARCHAR(255),FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(book_id) REFERENCES books(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO settings(setting_key,setting_value) VALUES('fine_per_day','10'),('loan_days','14');
